/**
 * Operações HTTP do recurso pedidos.
 */
import { apiRequest } from "../../../../support/api/client.js";

export function listarPedidos(query) {
  return apiRequest({ method: "GET", url: "/pedidos", qs: query });
}

export function criarPedido(corpo) {
  return apiRequest({ method: "POST", url: "/pedidos", body: corpo });
}

/**
 * Pedidos — fluxo principal de listagem e criação.
 */
import { criarPedido, listarPedidos } from "./_support/api.js";

describe("pedidos — fluxo principal", () => {
  // @endpoint GET /pedidos @cat CAT-01 @alvo listagem-devolve-colecao
  it("lista pedidos e devolve a coleção", () => {
    listarPedidos().then((resposta) => {
      expect(resposta.status, "status da listagem de pedidos").to.eq(200);
      expect(resposta.body, "corpo da listagem de pedidos").to.be.an("array");
    });
  });

  // @endpoint POST /pedidos @cat CAT-01 @alvo criacao-persistida
  it("cria um pedido e devolve o registro criado", () => {
    criarPedido({ situacao: "ABERTO" }).then((resposta) => {
      expect(resposta.status, "status da criação de pedido").to.eq(201);
      expect(resposta.body.situacao, "situação do pedido criado").to.eq("ABERTO");
    });
  });
  // @endpoint GET /pedidos @cat CAT-10 @alvo pagina-limita-quantidade
  it("limita a quantidade de itens quando a página é pedida", () => {
    listarPedidos({ page: 1, size: 1 }).then((resposta) => {
      expect(resposta.status, "status da listagem paginada").to.eq(200);
      expect(resposta.body, "itens da primeira página").to.have.lengthOf.at.most(1);
    });
  });

  // @endpoint POST /pedidos @cat CAT-11 @alvo repeticao-cria-registro-distinto
  it("cria registros distintos quando a mesma criação é repetida", () => {
    criarPedido({ situacao: "ABERTO" }).then((primeira) => {
      criarPedido({ situacao: "ABERTO" }).then((segunda) => {
        expect(segunda.status, "status da criação repetida").to.eq(201);
        expect(segunda.body.id, "identificador do pedido repetido").to.not.eq(primeira.body.id);
      });
    });
  });
});

/**
 * Pedidos — validações da superfície de entrada da criação.
 */
import { criarPedido, listarPedidos } from "./_support/api.js";

describe("pedidos — validações", () => {
  // @endpoint POST /pedidos @cat CAT-02 @campo situacao @alvo situacao-ausente
  it("recusa a criação quando situacao é omitida", () => {
    criarPedido({}).then((resposta) => {
      expect(resposta.status, "status ao omitir situacao").to.eq(400);
    });
  });

  // @endpoint POST /pedidos @cat CAT-03 @campo situacao @alvo situacao-fora-do-conjunto
  it("recusa situacao fora do conjunto permitido", () => {
    criarPedido({ situacao: "INVENTADA" }).then((resposta) => {
      expect(resposta.status, "status com situacao fora do conjunto").to.eq(400);
    });
  });

  // @endpoint POST /pedidos @cat CAT-05 @alvo corpo-escalar
  it("recusa corpo escalar na criação", () => {
    criarPedido("texto").then((resposta) => {
      expect(resposta.status, "status ao enviar corpo escalar").to.eq(400);
    });
  });
  // @endpoint GET /pedidos @cat CAT-06 @alvo filtro-por-cliente-inexistente
  it("devolve coleção vazia ao filtrar por cliente inexistente", () => {
    listarPedidos({ clienteId: "00000000-0000-0000-0000-000000000000" }).then((resposta) => {
      expect(resposta.status, "status do filtro por cliente inexistente").to.eq(200);
      expect(resposta.body, "coleção filtrada por cliente inexistente").to.be.empty;
    });
  });
});

/**
 * Pedidos — autenticação, autorização e campos controlados pelo servidor.
 */
import { criarPedido, listarPedidos } from "./_support/api.js";

describe("pedidos — segurança", () => {
  // @endpoint GET /pedidos @cat CAT-08 @alvo listagem-sem-credencial
  it("recusa a listagem sem credencial", () => {
    listarPedidos().then((resposta) => {
      expect(resposta.status, "status da listagem sem credencial").to.eq(401);
    });
  });

  // @endpoint POST /pedidos @cat CAT-09 @alvo id-controlado-pelo-servidor
  it("ignora o identificador enviado pelo cliente na criação", () => {
    criarPedido({ id: 999, situacao: "ABERTO" }).then((resposta) => {
      expect(resposta.body.id, "identificador do pedido criado").to.not.eq(999);
    });
  });
  // @endpoint POST /pedidos @cat CAT-08 @alvo criacao-sem-credencial
  it("recusa a criação sem credencial", () => {
    criarPedido({ situacao: "ABERTO" }).then((resposta) => {
      expect(resposta.status, "status da criação sem credencial").to.eq(401);
    });
  });
});
